def hidden_rule_fn(state):
    n = len(state)
    m = len(state[0])
    next_state = [[0]*m for _ in range(n)]
    for r in range(n):
        for c in range(m):
            cur = state[r][c]
            cc = (r + c) % 3
            # Collect neighborhood values based on coord-class
            neighbors = []
            if cc == 0:
                # class-0: diagonal tetrad (NE, NW, SE, SW)
                for dr, dc in [(-1,1), (-1,-1), (1,1), (1,-1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < n and 0 <= nc < m:
                        neighbors.append(state[nr][nc])
            elif cc == 1:
                # class-1: von Neumann (N, S, E, W)
                for dr, dc in [(-1,0), (1,0), (0,1), (0,-1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < n and 0 <= nc < m:
                        neighbors.append(state[nr][nc])
            elif cc == 2:
                # class-2: axial-2 (distance 2 along axes)
                for dr, dc in [(-2,0), (2,0), (0,2), (0,-2)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < n and 0 <= nc < m:
                        neighbors.append(state[nr][nc])
            # Count f0, f1, f2
            f0 = neighbors.count(0)
            f1 = neighbors.count(1)
            f2 = neighbors.count(2)
            # Majority vote; if tie, use cur
            counts = [(f0, 0), (f1, 1), (f2, 2)]
            counts.sort(reverse=True)
            if counts[0][0] > counts[1][0]:
                next_state[r][c] = counts[0][1]
            elif counts[0][0] == counts[1][0]:
                # tie between two or three
                if counts[0][0] == counts[2][0]:
                    # all equal
                    next_state[r][c] = cur
                else:
                    # tie between two highest
                    # pick the one that is NOT cur, or if both are cur, pick cur
                    tie_vals = [counts[0][1], counts[1][1]]
                    if cur in tie_vals:
                        next_state[r][c] = cur
                    else:
                        next_state[r][c] = tie_vals[0]
            else:
                next_state[r][c] = counts[1][1]
    return next_state
